			static readonly string[] Letters_DotGram = new string[128];

			static int TokenAt_DotGram(int[] starts, int count, int at)
			{
				var low  = 0;
				var high = count - 1;

				while (low <= high)
				{
					var middle = low + ((high - low) >> 1);
					var began  = starts[middle];

					if (began == at)
						return middle;

					if (began < at)
						low = middle + 1;
					else
						high = middle - 1;
				}

				// Where none begins there, the first one after it: `low` is where the search
				// ended, and the count where nothing is left to read.
				return low < count ? low : -1;
			}

			static string Text_DotGram(string source, int[] starts, int[] lengths, int from, int length)
			{
				if (length <= 0)
					return string.Empty;

				var began = starts[from];
				var ended = starts[from + length - 1] + lengths[from + length - 1];

				if (ended - began == 1 && source[began] < 128)
				{
					var one = source[began];

					return Letters_DotGram[one] ??= source.Substring(began, 1);
				}

				return source.Substring(began, ended - began);
			}

		/// <summary>What kind of answer a publication gave (docs/syntax.md §7.5).</summary>
		public enum Outcome
		{
			/// <summary>The input matched, and <c>Value</c> holds what it built.</summary>
			Success,

			/// <summary>The input was there and did not fit.</summary>
			NoMatch,

			/// <summary>The input ran out where more was needed.</summary>
			Starved,
		}

		/// <summary>What a publication answers with: the value, or why there is none.</summary>
		public readonly struct Match<T>
		{
			private readonly string[]? _expected;

			private readonly string[][]? _tied;

			private readonly string? _otherwise;

			private Match(
				Outcome outcome, T value, long position, int length,
				string[]? expected, string[][]? tied,
				string? otherwise)
			{
				Outcome    = outcome;
				Value      = value;
				Position   = position;
				Length     = length;
				_expected  = expected;
				_tied      = tied;
				_otherwise = otherwise;
			}

			/// <summary>Whether there is a value.</summary>
			public bool IsSuccess { get { return Outcome == Outcome.Success; } }

			/// <summary>
			/// Which kind of answer this is: the value, input that did not fit, or input
			/// that ran out (docs/syntax.md §7.5).
			/// </summary>
			public Outcome Outcome { get; }

			/// <summary>What was recognized. Meaningless unless <c>IsSuccess</c>.</summary>
			public T Value { get; }

			/// <summary>
			/// Why nothing was recognized, or null.
			/// </summary>
			/// <remarks>
			/// Built where it is asked for rather than where the match failed, and built
			/// again on each ask. A caller that only wants to know whether the input
			/// matched pays for none of it, which is most callers and every one in a loop
			/// over input that is expected to fail sometimes.
			/// </remarks>
			public string? Error
			{
				get
				{
					if (IsSuccess)
						return null;

					var expected = _expected;

					if (_tied != null)
					{
						var total = expected == null ? 0 : expected.Length;

						foreach (var each in _tied)
							total += each.Length;

						var merged = new string[total];
						var at     = 0;

						if (expected != null)
						{
							expected.CopyTo(merged, 0);
							at = expected.Length;
						}

						foreach (var each in _tied)
						{
							each.CopyTo(merged, at);
							at += each.Length;
						}

						expected = merged;
					}

					if (expected == null || expected.Length == 0)
						return _otherwise;

					// A rule that says what its own refusal says (docs/syntax.md §4's `on
					// fail`) writes it as one item, marked with a character no grammar can
					// write. Where one stands here it is the whole answer: the author took
					// the wording, and what else could have stood here is not it.
					for (var i = 0; i < expected.Length; i++)
						if (expected[i].Length > 0 && expected[i][0] == '\u0000')
							return expected[i].Substring(1);

					// Two sites may ask for the same thing — a literal written in two rules,
					// or the `<` that opens a type argument list in more than one — and a
					// reader is owed one mention of it rather than one per site. Copied
					// rather than compacted where it stands: without a tie this array is the
					// one the generator declared `static readonly`, and rewriting that would
					// change what every later failure says.
					if (expected.Length > 1)
					{
						var unique = new string[expected.Length];
						var kept   = 0;

						for (var i = 0; i < expected.Length; i++)
						{
							var seen = false;

							for (var j = 0; j < kept; j++)
								if (string.Equals(
										unique[j], expected[i], global::System.StringComparison.Ordinal))
								{
									seen = true;
									break;
								}

							if (!seen)
								unique[kept++] = expected[i];
						}

						if (kept < expected.Length)
						{
							expected = new string[kept];
							global::System.Array.Copy(unique, expected, kept);
						}
					}

					if (expected.Length == 1)
						return "Expected " + expected[0] + ".";

					return "Expected " +
						string.Join(", ", expected, 0, expected.Length - 1) +
						" or " + expected[expected.Length - 1] + ".";
				}
			}

			/// <summary>
			/// Where the match began, or how far the input could be followed before it
			/// failed. An offset into the whole input, so a <c>long</c>: an input may be a
			/// file larger than an <c>int</c> can index (docs/syntax.md §6.3).
			/// </summary>
			public long Position { get; }

			/// <summary>
			/// How much was matched, in input items, and zero when nothing was. An extent
			/// into a buffer rather than an offset into the input, so an <c>int</c>.
			/// </summary>
			public int Length { get; }

			internal static Match<T> Success(T value, long position, int length)
			{
				return new Match<T>(Outcome.Success, value, position, length, null, null, null);
			}

			internal static Match<T> Failed(
				Outcome outcome, string otherwise, long position, string[]? expected,
				string[][]? tied)
			{
				return new Match<T>(outcome, default!, position, 0, expected, tied, otherwise);
			}

			internal Match<TOther> Refusal<TOther>(long position, string otherwise)
			{
				return Match<TOther>.Failed(Outcome, _otherwise ?? otherwise, position, _expected, _tied);
			}
		}

		struct Failure
		{
			public int Position;

			public int OutOfInput;

			public string[]? Expected;

			public global::System.Collections.Generic.List<string[]>? ExpectedMore;

			// Nothing assigns this here: no reading of this grammar holds a lookahead.
			// A field nothing assigns is CS0649 in somebody else's build, which for one
			// that treats warnings as errors is a broken compilation of a file they did
			// not write.
			#pragma warning disable 0649
			public int Looking;
			#pragma warning restore 0649

			public bool Quiet;

			public bool Unasked;

			public int Doors;
		}

		[global::System.ThreadStatic]
		private static global::System.Collections.Generic.List<string[]>? _spareTies;

		private static global::System.Collections.Generic.List<string[]> Ties_DotGram()
		{
			var ties = _spareTies;

			if (ties == null)
				return new global::System.Collections.Generic.List<string[]>();

			_spareTies = null;

			return ties;
		}

		private static string[][]? Handed_DotGram(global::System.Collections.Generic.List<string[]>? ties)
		{
			if (ties == null)
				return null;

			var tied = ties.Count == 0 ? null : ties.ToArray();

			ties.Clear();
			_spareTies = ties;

			return tied;
		}

