		/// </summary>
		/// <remarks>
		/// Longest match. The machine is run until it can go no further and the last state
		/// that accepted is the answer, which is why a keyword beats the identifier it starts
		/// and <c>&gt;=</c> beats <c>&gt;</c> without either being written down as a rule.
		/// </remarks>
		/// <returns>Where the token ends, or <paramref name="pos"/> where none begins here.</returns>
		public static int Scan(global::System.ReadOnlySpan<char> text, int pos, out int kind)
		{
			var state = 0;
			var end   = pos;
			var found = 0;
			var p     = pos;

			while (p < text.Length)
			{
				var c    = text[p];
				var row  = Scan_States[state];
				var at   = c - (int)(row >> 32);
				int next;

				if ((uint)at < 128u)
					next = Scan_Cells[(int)row + at];
				else
				{
					next =
						Scan_Part0(state, c);
				}

				if (next < 0)
					goto Done;

				var again = next == state;

				state = next;
				p++;

				// A run of one class, which the row above already decided.
				if (again)
				{
					var over = Scan_Runs[state] << 8;

					while (p < text.Length)
					{
						var ahead = text[p];

						if (ahead > 255 || Scan_Running[over + ahead] == 0)
