				var row  = Scan_States[state];
				var at   = c - (int)(row >> 32);
				int next;

				if ((uint)at < 128u)
					next = Scan_Cells[(int)row + at];
				else
				{
					next =
						Scan_Part0(state, c);
				}

				if (next < 0)
					return false;

				state = next;
			}

			return true;
		}

